import pandas as pd,numpy as np
from sklearn.base import BaseEstimator,TransformerMixin
from sklearn.preprocessing import SplineTransformer,StandardScaler,OneHotEncoder
from sklearn.pipeline import make_pipeline
from sklearn.linear_model import Ridge
from sklearn.model_selection import KFold,cross_val_predict
from sklearn.metrics import mean_squared_error,mean_absolute_error
class CondSpline(BaseEstimator,TransformerMixin):
 def __init__(self,knots=3,deg=1,ht=True,route=False,combo=False):self.knots=knots;self.deg=deg;self.ht=ht;self.route=route;self.combo=combo
 def fit(self,X,y=None):
  self.nums=[c for c in X if c not in ['heat_treatment','route','Fe']]
  self.spl=SplineTransformer(n_knots=self.knots,degree=self.deg).fit(X[self.nums]);self.scaler=StandardScaler().fit(self.spl.transform(X[self.nums]))
  cats=[]
  if self.ht:cats+=['heat_treatment']
  if self.route:cats+=['route']
  self.oh=OneHotEncoder(drop=None,sparse_output=False).fit(X[['heat_treatment','route']])
  if self.combo:self.combos=sorted(set(X.heat_treatment+'_'+X.route))
  return self
 def transform(self,X):
  z=self.scaler.transform(self.spl.transform(X[self.nums])); oh=self.oh.transform(X[['heat_treatment','route']]); outs=[z,oh]
  p=0
  if self.ht:
   n=len(self.oh.categories_[0]);outs += [z*oh[:,[j]] for j in range(n)];p+=n
  if self.route:
   st=len(self.oh.categories_[0]);n=len(self.oh.categories_[1]);outs += [z*oh[:,[st+j]] for j in range(n)]
  if self.combo:
   co=np.array(X.heat_treatment+'_'+X.route);outs += [z*(co==j)[:,None] for j in self.combos]
  return np.hstack(outs)
